extract_object_init_decl() {


    awk '
        BEGIN { active = 1; depth = 0 }
        /^[[:space:]]*#if[[:space:]]+/ {
            depth++
            parent[depth] = active
            cond[depth] = ($0 ~ /^[[:space:]]*#if[[:space:]]+true[[:space:]]*$/)
            active = parent[depth] && cond[depth]
            next
        }
        /^[[:space:]]*#else/ {
            active = parent[depth] && !cond[depth]
            next
        }
        /^[[:space:]]*#endif/ {
            active = parent[depth]
            delete parent[depth]
            delete cond[depth]
            depth--
            next
        }
        active && /override/ && /init[[:space:]]*\([[:space:]]*\)/ {
            line = $0
            sub(/^[[:space:]]+/, "", line)
            sub(/[[:space:]]*\{.*/, "", line)
